import React, { Component, Fragment } from 'react';
import { connect } from 'react-redux';
import { bindActionCreators } from 'redux';
import { ActionCreators } from '../actions/index';
import { Table, HeaderRow, HeaderCell, Row, Cell } from '@jsroot/components/react-grid/index';
import LangHelper from '@jsroot/common/langHelper';
import { Form } from 'react-bootstrap';
import functions from '../functions';
import { PAGING_SIZES } from '@jsroot/common/constants';
import AutoRefresh from './AutoRefresh';

export class DataGrid extends Component {
    constructor(props) {
        super(props);
    }

    onPaging = (pageIndex, pageSize) => {
        const params = { ...this.props.gridParams };
        params.pageIndex = pageIndex;
        params.pageSize = pageSize;
        this.getGridData(params);
    };

    getGridData = params => {
        this.props.setGridParams(params);
        this.props.getGridData({ ...params }, data => functions.handleNewResendOptions(data, this.props.setResendOptions));
    };

    buildNotificationListHeader = isHost =>
        <HeaderRow>
            <HeaderCell colWidth={5}>{LangHelper.getResource('SymbolNo')}</HeaderCell>
            <HeaderCell colWidth={15}>
                <div>{LangHelper.getResource('NotificationID')}</div>
                <div>{LangHelper.getResource('ReferenceId')}</div>
            </HeaderCell>
            <HeaderCell colWidth={23}>{LangHelper.getResource('Sender')}/{LangHelper.getResource('NotificationType')}</HeaderCell>
            <HeaderCell colWidth={12}>{LangHelper.getResource('SendDateTimeGMTA8')}</HeaderCell>
            <HeaderCell colWidth={16}>{LangHelper.getResource('LetstalkName')}</HeaderCell>
            <HeaderCell colWidth={26}>{LangHelper.getResource('GroupHeadline')}</HeaderCell>
            <HeaderCell colWidth={19}>{LangHelper.getResource('Recipient')}</HeaderCell>
            <HeaderCell colWidth={20}>{LangHelper.getResource('Title')}/{LangHelper.getResource('Content')}</HeaderCell>
            <HeaderCell colWidth={12}>{LangHelper.getResource('Status')}</HeaderCell>
            {
                isHost && <HeaderCell colWidth={10}>{LangHelper.getResource('Action')}</HeaderCell>
            }
            {
                isHost && <HeaderCell colWidth={10}>
                    <input
                        type='button'
                        value={LangHelper.getResource('Resend')}
                        disabled={this.props.resendOptions.isDisabledResend}
                        onClick={this.resendNotificationAll}
                    />
                    {
                        this.props.resendOptions.isHaveResendAll &&
                        <Form.Control
                            className='checkbox-cell-style margin-top-10'
                            type='checkbox'
                            onChange={this.handleChangeResendAllCheckbox}
                            checked={this.props.resendOptions.isCheckedAll}
                        />
                    }
                </HeaderCell>
            }
        </HeaderRow>;

    buildNotificationListBody = isHost => {
        const { pageIndex, pageSize } = this.props.gridParams;

        this.startIndex = (pageIndex - 1) * pageSize + 1;

        if (this.props.notificationListGridData.data.length > 0) {
            return this.props.notificationListGridData.data.map((item, index) => this.renderRow(item, index, isHost));
        }

        return [<Row key={`body${1}`} className='no-data' ><Cell colSpan={isHost ? 11 : 9}>{LangHelper.getResource('ThereIsNoData')}</Cell></Row>];
    };

    openContentPopup = item => {
        this.props.setContentPopup({
            show: true,
            data: item
        });

        this.setIsRefresh(false);
    };

    openViewDetailPopup = item => {
        this.props.setViewDetailPopup({
            show: true,
            data: item
        });

        this.setIsRefresh(false);
    };

    setIsRefresh = isRefresh => {
        this.setNotShouldResetScrollPosition();
        this.props.setIsRefresh(isRefresh);
    };

    setNotShouldResetScrollPosition = () =>
        this.props.setResendOptions({
            ...this.props.resendOptions,
            shouldResetScrollPosition: false
        });

    isError = status => status.toLowerCase() === LangHelper.getResource('Error').toLowerCase();
    isResolved = status => status.toLowerCase() === LangHelper.getResource('Resolved').toLowerCase();
    isDuplicated = status => status.toLowerCase() === LangHelper.getResource('Duplicated').toLowerCase();

    validateResend = notificationId => {
        this.setIsRefresh(false);
        this.props.validateResend({
            notificationIds: notificationId,
            isSingle: true
        });
    };

    renderRow = (item, index, isHost) =>
        <Row key={index} >
            <Cell className='text-center'>{index + this.startIndex}</Cell>
            {this.renderReferenceId(item)}
            <Cell>
                <div>{item.sender}</div>
                <div>{item.notificationTypeName}</div>
            </Cell>
            <Cell className='text-center'>
                <div>{item.sendDateString}</div>
                <div>{item.sendTimeString}</div>
            </Cell>
            <Cell>{item.letstalkName}</Cell>
            <Cell className='text-center'>{functions.getHeadlines(item.headlines)}</Cell>
            <Cell>{functions.getRecipients(item.recipients)}</Cell>
            <Cell className='link-click' onClick={() => this.openContentPopup(item)}>{item.title}</Cell>
            <Cell className={`text-center status-font ${item.status.toLowerCase()}-color`}>{LangHelper.getResource(item.status)}</Cell>
            {
                isHost &&
                <Cell className='text-center'>
                    {
                        (this.isError(item.status) || this.isResolved(item.status)) &&
                            <div
                                onClick={() => this.openViewDetailPopup(item)}
                                className='action-style link-click'
                            >{LangHelper.getResource('ViewDetail')}</div>
                    }
                    {
                        this.isError(item.status) &&
                        <div
                            onClick={() => this.validateResend(item.notificationId)}
                            className='action-style link-click'
                        >{LangHelper.getResource('Resend')}</div>
                    }
                </Cell>
            }
            {
                isHost &&
                <Cell className='text-center'>
                    { this.isError(item.status) && <Form.Control className='checkbox-cell-style'
                        id={`resend-${item.notificationId}-${item.messageId}`}
                        type='checkbox'
                        checked={this.props.resendOptions.dataList[index] && this.props.resendOptions.dataList[index].isResent}
                        onChange={() => this.handleChangeResendCheckbox(index)} />}
                </Cell>
            }
        </Row>;

    renderReferenceId = item => {
        return  <Cell className='text-center'>
                    <div>{item.notificationId}</div>
                    <div>{item.dataSource === 'MessageId' ? `(Msg: ${item.referenceId})` : item.referenceId > 0 && `(Log: ${item.referenceId})`}</div>
                    {
                        this.isDuplicated(item.status) && <div>{`(Related ID: ${item.relatedNotificationIds})`}</div>
                    }
                </Cell>;
    };

    handleChangeResendCheckbox = index => {
        const dataList = [...this.props.resendOptions.dataList];
        dataList[index].isResent = !this.props.resendOptions.dataList[index].isResent;
        const isDisabledResend = dataList.filter(item => this.isError(item.status) && item.isResent).length <= 0;
        const notCheckedDataList = dataList.filter(item => this.isError(item.status) && !item.isResent);
        this.setIsRefresh(isDisabledResend);
        this.props.setResendOptions({
            isCheckedAll: notCheckedDataList.length <= 0,
            isDisabledResend,
            isHaveResendAll: this.props.resendOptions.isHaveResendAll,
            shouldResetScrollPosition: false,
            dataList
        });
    };

    handleChangeResendAllCheckbox = () => {
        const checked = !this.props.resendOptions.isCheckedAll;
        const dataList = [...this.props.resendOptions.dataList];
        dataList.forEach(item => item.isResent = checked);
        this.setIsRefresh(!checked);
        this.props.setResendOptions({
            isCheckedAll: checked,
            isDisabledResend: !checked,
            isHaveResendAll: this.props.resendOptions.isHaveResendAll,
            shouldResetScrollPosition: false,
            dataList
        });
    };

    resendNotificationAll = () => {
        const resendList = this.props.resendOptions.dataList.filter(item => this.isError(item.status) && item.isResent);
        this.props.validateResend({
            notificationIds: resendList.map(item => item.notificationId).join(','),
            isSingle: false
        });
    };

    render() {
        if (!this.props.notificationListGridData || !this.props.notificationListGridData.data) {
            return null;
        }

        const { totalItems } = this.props.notificationListGridData;
        const { pageIndex, pageSize } = this.props.gridParams;
        const { isHost } = this.props;

        const pagingOption = {
            PageIndex: pageIndex,
            PageSize: pageSize,
            TotalItem: totalItems,
            PageList: PAGING_SIZES
        };

        return (
            <Fragment>
                <div className='d-flex table-title justify-content-between align-items-center'>
                    <div>{LangHelper.getResource('NotificationList')}</div>
                    <AutoRefresh />
                </div>
                <Table
                    minWidth={960}
                    maxWidth={document.getElementById('app-container').clientWidth}
                    autoWidth
                    header={this.buildNotificationListHeader(isHost)}
                    body={this.buildNotificationListBody(isHost)}
                    isPaging
                    pageOption={pagingOption}
                    onPaging={this.onPaging}
                    containerPadding={0}
                    shouldResetScrollPosition={this.props.resendOptions.shouldResetScrollPosition}
                />
            </Fragment>
        );
    }
}

const mapDispatchToProps = dispatch => bindActionCreators(ActionCreators, dispatch);

const mapStateToProps = state => {
    const {
        gridParams,
        notificationListGridData,
        resendOptions,
        isRefresh
    } = state;

    return {
        gridParams,
        notificationListGridData,
        resendOptions,
        isRefresh
    };
};

export default connect(mapStateToProps, mapDispatchToProps)(DataGrid);